INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (7, "", "vo_minigame_1013_top_talk_7_002", 21, "", "vo_minigame_1013", 0, 0, "", 7015, "");
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (7, 0, "彼らが私に逆らわずに\n努力したからこそ、\n得たものもありますし\n…感謝しておきますわ", 11, 0.5, 129911, 1, 6, 0, 7016, 0);
