INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (8, "", "vo_minigame_1013_top_talk_8_002", 21, "", "vo_minigame_1013", 0, 0, "", 8015, "");
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (8, 0, "くっ、そう言われると\n悔しいな…！\nならこの行軍訓練で\n逆転してやるぜ！", 11, 0.3, 129811, 1, 7, 0, 8016, 0);
